Here is the commit message:
pktgen: adjust flag NO_TIMESTAMP to be more pktgen compliant

Allow flag NO_TIMESTAMP to turn timestamping on again, like other flags,
with a negation of the flag like !NO_TIMESTAMP.

Also document the option flag NO_TIMESTAMP.

Fixes: afb84b626184 ("pktgen: add flag NO_TIMESTAMP to disable timestamping")
Signed-off-by: Jesper Dangaard Brouer <brouer@redhat.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The `NO_TIMESTAMP` flag was not functioning as intended, as it only disabled timestamping without providing a way to re-enable it through a negation. This inconsistency in flag behavior led to confusion and limited usability for users who expected to toggle the timestamping feature on and off.

Here is the patch:

 static ssize_t pktgen_if_write(struct file *file,
 			       const char __user * user_buffer, size_t count,
 			       loff_t * offset)
 {
 	struct seq_file *seq = file->private_data;
 	struct pktgen_dev *pkt_dev = seq->private;
 	int i, max, len;
 	char name[16], valstr[32];
 	unsigned long value = 0;
 	char *pg_result = NULL;
 	int tmp = 0;
 	char buf[128];

 	pg_result = &(pkt_dev->result[0]);

 	if (count < 1) {
 		pr_warn("wrong command format\n");
 		return -EINVAL;
 	}

 	max = count;
 	tmp = count_trail_chars(user_buffer, max);
 	if (tmp < 0) {
 		pr_warn("illegal format\n");
 		return tmp;
 	}
 	i = tmp;

 	/* Read variable name */

 	len = strn_len(&user_buffer[i], sizeof(name) - 1);
 	if (len < 0)
 		return len;

 	memset(name, 0, sizeof(name));
 	if (copy_from_user(name, &user_buffer[i], len))
 		return -EFAULT;
 	i += len;

 	max = count - i;
 	len = count_trail_chars(&user_buffer[i], max);
 	if (len < 0)
 		return len;

 	i += len;

 	if (debug) {
 		size_t copy = min_t(size_t, count, 1023);
 		char tb[copy + 1];
 		if (copy_from_user(tb, user_buffer, copy))
 			return -EFAULT;
 		tb[copy] = 0;
 		pr_debug("%s,%lu  buffer -:%s:-\n",
 			 name, (unsigned long)count, tb);
 	}

 	if (!strcmp(name, "min_pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->min_pkt_size) {
 			pkt_dev->min_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: min_pkt_size=%u",
 			pkt_dev->min_pkt_size);
 		return count;
 	}

 	if (!strcmp(name, "max_pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->max_pkt_size) {
 			pkt_dev->max_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: max_pkt_size=%u",
 			pkt_dev->max_pkt_size);
 		return count;
 	}

 	/* Shortcut for min = max */

 	if (!strcmp(name, "pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->min_pkt_size) {
 			pkt_dev->min_pkt_size = value;
 			pkt_dev->max_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: pkt_size=%u", pkt_dev->min_pkt_size);
 		return count;
